// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint256 startBlock, address actor) public {
        vm.assume(actor != address(0));
        startBlock = bound(startBlock, 1, type(uint248).max - 2);

        // Lock a guess at startBlock; target block is startBlock + 1.
        vm.roll(startBlock);
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(actor, startBlock)));

        // Call settle() exactly AT the target block.
        vm.roll(startBlock + 1);
        vm.prank(actor);
        try c.settle() { /* mutant settles here */ } catch { /* reference reverts */ }

        // Rule: the guess must still be locked (settle must not have succeeded
        // at the target block), so a second lockInGuess must revert.
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(actor, startBlock + 1))) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
